# area: context_managers
# hypothesis: A with-statement whose __exit__ is annotated -> bool may swallow exceptions, so code after the block stays reachable, while -> None lets the checker treat the following return as unreachable.
# spec: typing spec - an __exit__ return type of bool means the context manager may suppress exceptions.
from typing import reveal_type


class Swallow:
    def __enter__(self) -> int:
        return 1

    def __exit__(self, *args: object) -> bool:
        return True


class Propagate:
    def __enter__(self) -> str:
        return 'p'

    def __exit__(self, *args: object) -> None:
        return None


def swallowed() -> int:
    with Swallow() as v:
        reveal_type(v)
        raise ValueError('boom')
    return 2


def propagated() -> int:
    with Propagate() as s:
        reveal_type(s)
        raise ValueError('boom')
    return 3


print(swallowed())
try:
    print(propagated())
except ValueError:
    print('propagated')
